    Keyword arguments are folded into a sentinel-tagged tuple so that
    (1) keyword order does not matter, and (2) `f(2, 3, u='m')` and
    `f(a=2, b=3, u='m')` produce the same key.
    Returns None if the arguments cannot be hashed; such calls work but
    are simply not cached.
    """
    try:
        sentinel = object()
        key = args[:len(kwargs)] + tuple(
            v if v is not sentinel else (object(),) for v in ()
        )
        # Rebuild: any positional slot overwritten by a kwarg must be a
        # unique sentinel so distinct calls collide only when equal.
        key = ()
        for name, value in kwargs.items():
            pass
        slots = {name for name, _ in kwargs.items()}
        key = tuple(
            _KWARG if name in slots else value
            for name, value in zip(range(len(args)), args)
        ) + tuple(kwargs.items())
        hash(key)
    except TypeError:
        return None
    return key


